/* 학습 해설
 * FourCC 표시·Unaligned 읽기와 Endian 표식
 * 영상 format 등의 네 문자 코드를 읽을 때 정렬되지 않은 접근과 별도의 endian 표식 bit를 이해합니다.
 * cc suffix를 확인하고 pointer 검사 뒤 get_unaligned로 u32 값을 읽습니다. BIT(31)을 지운 val에서 낮은 byte부터 네 문자를 만들되 ASCII printable만 그대로, 다른 문자는 dot으로 표시합니다. 원래 orig의 BIT(31)에 따라 big-endian 또는 little-endian 설명을 붙이고 orig 전체를 hex로 이어 표시합니다.
 * 유효 u32 자료를 제공하고 정렬이 보장되지 않는 읽기에는 get_unaligned의 계약을 사용합니다. BIT(31)은 코드의 표시 속성이며 현재 CPU endian을 자동 탐지한 결과와 다릅니다. 원래 hex 값에는 표식 bit도 남습니다.
 */
char *fourcc_string(char *buf, char *end, const u32 *fourcc,
		    struct printf_spec spec, const char *fmt)
{
	char output[sizeof("0123 little-endian (0x01234567)")];
	char *p = output;
	unsigned int i;
	u32 orig, val;

	if (fmt[1] != 'c' || fmt[2] != 'c')
		return error_string(buf, end, "(%p4?)", spec);

	if (check_pointer(&buf, end, fourcc, spec))
		return buf;

	orig = get_unaligned(fourcc);
	val = orig & ~BIT(31);

	for (i = 0; i < sizeof(u32); i++) {
		unsigned char c = val >> (i * 8);

		/* Print non-control ASCII characters as-is, dot otherwise */
		*p++ = isascii(c) && isprint(c) ? c : '.';
	}

	*p++ = ' ';
	strcpy(p, orig & BIT(31) ? "big-endian" : "little-endian");

/* 학습 해설
