 * Pointer 사전 검사 뒤 d selector는 dma_addr_t, p와 그 외는 phys_addr_t로 역참조합니다. 선택 타입의 sizeof와 값을 special_hex_number에 전달합니다. 읽기용 pointer 자체를 출력하지 않고 저장된 address value를 출력합니다.
 * Format이 요구하는 타입의 실제 객체를 전달합니다. CPU 물리 주소와 device가 사용하는 DMA 주소를 언제나 같은 값으로 가정하지 않습니다. 출력된 값을 가상 pointer로 바로 역참조하지 않습니다.
 */
char *address_val(char *buf, char *end, const void *addr,
		  struct printf_spec spec, const char *fmt)
{
	unsigned long long num;
	int size;

	if (check_pointer(&buf, end, addr, spec))
		return buf;

	switch (fmt[1]) {
	case 'd':
		num = *(const dma_addr_t *)addr;
		size = sizeof(dma_addr_t);
		break;
	case 'p':
	default:
		num = *(const phys_addr_t *)addr;
		size = sizeof(phys_addr_t);
		break;
	}

	return special_hex_number(buf, end, num, size);
}

