 * Bitmap Set Clear·첫 Mask와 마지막 Mask
 * 임의 연속 bit 구간을 변경할 때 부분 word 두 개와 그 사이 전체 word를 다루는 원리를 배웁니다.
 * Start의 word와 BITMAP_FIRST_WORD_MASK로 시작합니다. 남은 len이 현재 word의 남은 bit 수 이상이면 mask를 적용하고 다음 word부터 full mask를 씁니다. 마지막 길이가 남으면 BITMAP_LAST_WORD_MASK(start+len_original)와 결합합니다. Clear는 같은 구조에서 mask의 NOT를 AND합니다.
 * Start와 비음수 len의 합이 유효 배열 범위에 들어가도록 합니다. Bitmap 저장 용량을 이 helper가 인자로 받지 않아 자동 범위 검사를 하지 않습니다. 복수 word 변경은 전체가 하나의 원자적 동작이 아닙니다.
 */
void __bitmap_set(unsigned long *map, unsigned int start, int len)
{
	unsigned long *p = map + BIT_WORD(start);
	const unsigned int size = start + len;
	int bits_to_set = BITS_PER_LONG - (start % BITS_PER_LONG);
	unsigned long mask_to_set = BITMAP_FIRST_WORD_MASK(start);

	while (len - bits_to_set >= 0) {
		*p |= mask_to_set;
		len -= bits_to_set;
		bits_to_set = BITS_PER_LONG;
		mask_to_set = ~0UL;
		p++;
	}
	if (len) {
		mask_to_set &= BITMAP_LAST_WORD_MASK(size);
		*p |= mask_to_set;
	}
}
EXPORT_SYMBOL(__bitmap_set);

void __bitmap_clear(unsigned long *map, unsigned int start, int len)
{
	unsigned long *p = map + BIT_WORD(start);
	const unsigned int size = start + len;
	int bits_to_clear = BITS_PER_LONG - (start % BITS_PER_LONG);

/* 학습 해설
 * Bitmap Zero Area·Alignment Offset과 재검색
 * 연속 빈 자원 범위를 찾을 때 단일 빈 bit 탐색·정렬·전체 구간 검사로 후보를 좁히는 원리를 배웁니다.
 * Find_next_zero_bit로 시작 후보를 얻고 index+align_offset을 align_mask로 올림한 뒤 offset을 뺍니다. End=index+nr가 size를 넘으면 그 end를 반환합니다. 후보 구간에 set bit가 있으면 그 위치+1을 새 start로 하여 재검색합니다. Set bit가 없으면 index를 반환합니다.
 * align_mask는 2의 거듭제곱보다 1 작은 값이고 합·끝 계산의 유효 범위를 caller가 보장합니다. 찾은 뒤 실제 예약은 별도 동작이므로 공유 bitmap의 검색·표시 사이를 동기화합니다. 실패 값이 항상 size 하나라고 가정하지 않습니다.
 */
unsigned long bitmap_find_next_zero_area_off(unsigned long *map,
					     unsigned long size,
					     unsigned long start,
					     unsigned int nr,
					     unsigned long align_mask,
					     unsigned long align_offset)
{
	unsigned long index, end, i;
again:
	index = find_next_zero_bit(map, size, start);

	/* Align allocation */
	index = __ALIGN_MASK(index + align_offset, align_mask) - align_offset;

	end = index + nr;
	if (end > size)
		return end;
	i = find_next_bit(map, end, index);
	if (i < end) {
		start = i + 1;
		goto again;
	}
	return index;
}
EXPORT_SYMBOL(bitmap_find_next_zero_area_off);

/* 학습 해설
 * Bitmap Remap·위치 순번과 Modulo 대상
 * Set bit의 실제 위치와 집합 안에서 몇 번째인지라는 순번을 서로 변환하는 mapping을 배웁니다.
 * bitmap_pos_to_ord는 유효 set 위치인지 확인하고 그 앞의 weight를 순번으로 반환합니다. Remap은 src의 각 set bit를 old 집합 순번 n으로 바꾸고 new의 n%weight(new)번째 set 위치로 보냅니다. Old 밖이거나 new가 비었으면 원래 위치를 유지합니다. Dst==src이면 아무 변화 없이 반환하고 다른 dst는 먼저 clear합니다. Bitremap은 한 위치만 같은 규칙으로 변환합니다.
 * Dst가 입력 mapping 자료를 파괴하지 않게 분리하고 모든 bitmap의 유효 범위를 맞춥니다. Modulo 때문에 여러 원소가 같은 위치로 모일 수 있음을 이해합니다. In-place 호출을 실제 remapping 지원으로 해석하지 않습니다.
 */
void bitmap_remap(unsigned long *dst, const unsigned long *src,
		const unsigned long *old, const unsigned long *new,
		unsigned int nbits)
{
	unsigned int oldbit, w;

	if (dst == src)		/* following doesn't handle inplace remaps */
		return;
	bitmap_zero(dst, nbits);

	w = bitmap_weight(new, nbits);
	for_each_set_bit(oldbit, src, nbits) {
		int n = bitmap_pos_to_ord(old, oldbit, nbits);

		if (n < 0 || w == 0)
			set_bit(oldbit, dst);	/* identity map */
		else
			set_bit(find_nth_bit(new, nbits, n % w), dst);
	}
}
EXPORT_SYMBOL(bitmap_remap);

/**
 * bitmap_bitremap - Apply map defined by a pair of bitmaps to a single bit
 *	@oldbit: bit position to be mapped
 *	@old: defines domain of map
 *	@new: defines range of map
 *	@bits: number of bits in each of these bitmaps
 *
 * Let @old and @new define a mapping of bit positions, such that
 * whatever position is held by the n-th set bit in @old is mapped
 * to the n-th set bit in @new.  In the more general case, allowing
 * for the possibility that the weight 'w' of @new is less than the
 * weight of @old, map the position of the n-th set bit in @old to
 * the position of the m-th set bit in @new, where m == n % w.
 *
 * The positions of unset bits in @old are mapped to themselves
 * (the identity map).
 *
 * Apply the above specified mapping to bit position @oldbit, returning
 * the new bit position.
 *
 * For example, lets say that @old has bits 4 through 7 set, and
 * @new has bits 12 through 15 set.  This defines the mapping of bit
 * position 4 to 12, 5 to 13, 6 to 14 and 7 to 15, and of all other
 * bit positions unchanged.  So if say @oldbit is 5, then this routine
 * returns 13.
 */

/* 학습 해설
 * Bitmap Onto·밀집 순번을 희소 위치로
 * 밀집된 선택 번호를 sparse 자원 집합의 실제 위치로 옮기는 mapping 원리를 배웁니다.
 * CONFIG_NUMA의 bitmap_onto는 dst를 clear하고 relmap의 set 위치 n을 순회하면서 순번 m을 증가시킵니다. Orig의 bit m이 켜져 있으면 dst의 실제 bit n을 켭니다. Relmap의 weight 이상인 orig 번호는 어떤 위치에도 대응하지 않습니다. Dst==orig이면 변경 없이 반환합니다.
 * Orig를 자원 실제 위치가 아니라 relmap의 0-based 선택 순번 집합으로 사용합니다. Dst와 mapping 입력을 분리합니다. 필요하면 먼저 fold로 순번을 대상 weight 안으로 줄이되 빈 relmap 조건을 확인합니다.
 */
void bitmap_onto(unsigned long *dst, const unsigned long *orig,
			const unsigned long *relmap, unsigned int bits)
{
	unsigned int n, m;	/* same meaning as in above comment */

	if (dst == orig)	/* following doesn't handle inplace mappings */
		return;
	bitmap_zero(dst, bits);

	/*
	 * The following code is a more efficient, but less
	 * obvious, equivalent to the loop:
	 *	for (m = 0; m < bitmap_weight(relmap, bits); m++) {
	 *		n = find_nth_bit(orig, bits, m);
	 *		if (test_bit(m, orig))
	 *			set_bit(n, dst);
	 *	}
	 */

	m = 0;
	for_each_set_bit(n, relmap, bits) {
		/* m == bitmap_pos_to_ord(relmap, n, bits) */
		if (test_bit(m, orig))
			set_bit(n, dst);
		m++;
	}

/* 학습 해설
 * Bitmap Fold·Modulo 충돌과 크기 조건
 * 더 큰 선택 번호를 작은 번호 공간으로 접을 때 modulo와 중복 합쳐짐을 이해합니다.
 * CONFIG_NUMA의 bitmap_fold는 dst!=orig일 때 목적을 clear하고 orig의 각 set 위치 oldbit에 대해 oldbit%sz를 dst에 set합니다. 서로 다른 위치가 같은 나머지를 가지면 하나의 bit로 합쳐집니다. Dst==orig이면 변경 없이 반환합니다. Sz=0의 별도 방어 branch는 없습니다.
 * Sz는 양수이고 결과 나머지 위치가 목적 유효 공간에 들어가도록 합니다. 원소 개수가 항상 보존되는 permutation이라고 생각하지 않습니다. 빈 relmap weight를 그대로 divisor로 넘기지 않습니다.
 */
void bitmap_fold(unsigned long *dst, const unsigned long *orig,
			unsigned int sz, unsigned int nbits)
{
	unsigned int oldbit;

	if (dst == orig)	/* following doesn't handle inplace mappings */
		return;
	bitmap_zero(dst, nbits);

	for_each_set_bit(oldbit, orig, nbits)
		set_bit(oldbit % sz, dst);
}
#endif /* CONFIG_NUMA */

unsigned long *bitmap_alloc(unsigned int nbits, gfp_t flags)
{
	return kmalloc_array(BITS_TO_LONGS(nbits), sizeof(unsigned long),
			     flags);
}
EXPORT_SYMBOL(bitmap_alloc);

unsigned long *bitmap_zalloc(unsigned int nbits, gfp_t flags)
{
	return bitmap_alloc(nbits, flags | __GFP_ZERO);
}
EXPORT_SYMBOL(bitmap_zalloc);

/* 학습 해설
 * Bitmap 할당·Word 올림과 Node 선택
 * 필요 bit 수를 저장 배열 크기로 바꾸고 초기화·NUMA 요청 옵션을 전달하는 방법을 배웁니다.
 * Bitmap_alloc은 BITS_TO_LONGS(nbits)개 unsigned long을 kmalloc_array로 요청합니다. Zalloc은 __GFP_ZERO를 OR합니다. Node variant는 kmalloc_array_node에 node를 전달하고 node zalloc도 ZERO를 추가합니다. Bitmap_free는 kfree로 해제합니다.
 * 성공 여부와 선택 flags의 sleep·실패 계약을 확인하고 할당 수명에 맞춰 free합니다. Alloc과 zalloc의 초기 자료 차이를 구분합니다. Node 인자를 실제 placement의 무조건 보장이라고 일반화하지 않습니다.
 */
unsigned long *bitmap_alloc(unsigned int nbits, gfp_t flags)
{
	return kmalloc_array(BITS_TO_LONGS(nbits), sizeof(unsigned long),
			     flags);
}
EXPORT_SYMBOL(bitmap_alloc);

unsigned long *bitmap_zalloc(unsigned int nbits, gfp_t flags)
{
	return bitmap_alloc(nbits, flags | __GFP_ZERO);
}
EXPORT_SYMBOL(bitmap_zalloc);

unsigned long *bitmap_alloc_node(unsigned int nbits, gfp_t flags, int node)
{
	return kmalloc_array_node(BITS_TO_LONGS(nbits), sizeof(unsigned long),
				  flags, node);
}
EXPORT_SYMBOL(bitmap_alloc_node);

unsigned long *bitmap_zalloc_node(unsigned int nbits, gfp_t flags, int node)
{
	return bitmap_alloc_node(nbits, flags | __GFP_ZERO, node);
}
EXPORT_SYMBOL(bitmap_zalloc_node);

/* 학습 해설
 * Devm Bitmap·Action 등록 실패의 Reset
 * Device 수명에 맞춰 자원을 정리할 때 allocation과 cleanup 등록을 하나의 성공 조건으로 만드는 원리를 배웁니다.
 * 일반 bitmap allocation이 실패하면 NULL입니다. 성공하면 devm_add_action_or_reset에 devm_bitmap_free와 bitmap을 넘깁니다. 등록이 실패하면 action_or_reset이 해제 동작을 수행하고 wrapper는 NULL을 반환합니다. 성공하면 device 정리 시 action이 bitmap_free를 호출합니다. Zalloc variant는 ZERO flag를 더합니다.
 * Device 관리 자원의 수명과 manual allocation을 구분합니다. Action 등록 실패에서 이미 reset된 객체를 다시 free하지 않습니다. 성공한 devm 자원도 임의 manual free로 중복 cleanup이 생기지 않게 관리합니다.
 */
unsigned long *devm_bitmap_alloc(struct device *dev,
				 unsigned int nbits, gfp_t flags)
{
	unsigned long *bitmap;
	int ret;

	bitmap = bitmap_alloc(nbits, flags);
	if (!bitmap)
		return NULL;

	ret = devm_add_action_or_reset(dev, devm_bitmap_free, bitmap);
	if (ret)
		return NULL;

	return bitmap;
}
EXPORT_SYMBOL_GPL(devm_bitmap_alloc);

unsigned long *devm_bitmap_zalloc(struct device *dev,
				  unsigned int nbits, gfp_t flags)
{
	return devm_bitmap_alloc(dev, nbits, flags | __GFP_ZERO);
}
EXPORT_SYMBOL_GPL(devm_bitmap_zalloc);

#if BITS_PER_LONG == 64

/* 학습 해설
 * Bitmap 배열 변환·U32 U64와 Tail Clear
 * Native unsigned long bitmap과 명시적 폭의 숫자 배열을 변환할 때 host order와 마지막 유효 bit를 이해합니다.
 * 64bit long의 from_arr32는 u32 두 개를 낮은 32bit와 높은 32bit로 묶고 to_arr32는 반대로 나눕니다. 32bit long의 arr64 변환은 u64를 낮은 word와 필요한 높은 word로 나누거나 합칩니다. 각 변환은 마지막 유효 bit 밖을 clear합니다. Header의 같은 폭 경로는 copy_clear_tail을 사용합니다.
 * 입력과 목적의 실제 원소 개수 및 host byte order 계약을 맞춥니다. Network wire encoding으로 자동 변환하는 함수가 아닙니다. 64bit 배열과 작은 마지막 공간의 크기를 실제로 계산하고 CONFIG별 선택 경로를 확인합니다.
 */
void bitmap_from_arr32(unsigned long *bitmap, const u32 *buf, unsigned int nbits)
{
	unsigned int i, halfwords;

	halfwords = DIV_ROUND_UP(nbits, 32);
	for (i = 0; i < halfwords; i++) {
		bitmap[i/2] = (unsigned long) buf[i];
		if (++i < halfwords)
			bitmap[i/2] |= ((unsigned long) buf[i]) << 32;
	}

	/* Clear tail bits in last word beyond nbits. */
	if (nbits % BITS_PER_LONG)
		bitmap[(halfwords - 1) / 2] &= BITMAP_LAST_WORD_MASK(nbits);
}
EXPORT_SYMBOL(bitmap_from_arr32);

/**
 * bitmap_to_arr32 - copy the contents of bitmap to a u32 array of bits
 *	@buf: array of u32 (in host byte order), the dest bitmap
 *	@bitmap: array of unsigned longs, the source bitmap
 *	@nbits: number of bits in @bitmap
 */
void bitmap_to_arr32(u32 *buf, const unsigned long *bitmap, unsigned int nbits)
{
	unsigned int i, halfwords;

/* 학습 해설
 * Bitmap 사용자 입력·복사와 Parser 수명
 * 사용자 공간의 주소를 커널 parser가 바로 읽지 않고 안전하게 복사한 뒤 해석하는 경계를 배웁니다.
 * bitmap_parse_user와 bitmap_parselist_user는 memdup_user_nul로 ulen byte를 복사하고 마지막 NUL 공간을 확보합니다. ERR_PTR이면 PTR_ERR를 즉시 반환합니다. 성공한 복사본은 hex 또는 list parser에 전달하고 parser 성공·실패와 관계없이 kfree합니다. Hex wrapper의 UINT_MAX는 실제 할당 길이가 아니라 이미 NUL 종료된 입력을 끝까지 읽는 parser 계약입니다.
 * 사용자 입력 길이는 byte 단위이며 목적 bitmap의 nmaskbits는 bit 단위입니다. 복사 실패와 문법 오류를 나눠 처리합니다. Parser 오류가 목적 배열의 원상 복구를 보장하지 않으므로 실패 결과를 적용하지 않습니다.
 */
int bitmap_parse_user(const char __user *ubuf,
			unsigned int ulen, unsigned long *maskp,
			int nmaskbits)
{
	char *buf;
	int ret;

	buf = memdup_user_nul(ubuf, ulen);
	if (IS_ERR(buf))
		return PTR_ERR(buf);

	ret = bitmap_parse(buf, UINT_MAX, maskp, nmaskbits);

	kfree(buf);
	return ret;
}
EXPORT_SYMBOL(bitmap_parse_user);

/**
 * bitmap_print_to_pagebuf - convert bitmap to list or hex format ASCII string
 * @list: indicates whether the bitmap must be list
 * @buf: page aligned buffer into which string is placed
 * @maskp: pointer to bitmap to convert
 * @nmaskbits: size of bitmap, in bits
 *
 * Output format is a comma-separated list of decimal numbers and
 * ranges if list is specified or hex digits grouped into comma-separated
 * sets of 8 digits/set. Returns the number of characters written to buf.
 *
 * It is assumed that @buf is a pointer into a PAGE_SIZE, page-aligned
 * area and that sufficient storage remains at @buf to accommodate the
 * bitmap_print_to_pagebuf() output. Returns the number of characters
 * actually printed to @buf, excluding terminating '\0'.
 */

/* 학습 해설
 * Bitmap Page 출력·남은 공간과 실제 길이
 * Sysfs의 한 page 출력 규약과 문자열 길이 제한을 bitmap 형식 선택에 연결합니다.
 * len은 PAGE_SIZE-offset_in_page(buf)입니다. List이면 %*pbl, hex이면 %*pb에 nmaskbits와 maskp를 넘기고 newline을 붙입니다. Scnprintf는 저장한 문자 수를 NUL 제외하고 반환합니다. Page 중간 주소라면 전체 page 크기 대신 그 주소 이후 남은 공간만 사용할 수 있습니다.
 * Page 경계에 맞는 저장공간 안의 buf를 제공하고 출력이 남은 공간에 들어갈지 확인합니다. 반환값을 잘려 나오기 전 전체 문자열의 요구 길이로 해석하지 않습니다. 큰 bitmap의 전체 출력에는 offset/count를 가진 별도 API를 고려합니다.
 */
int bitmap_print_to_pagebuf(bool list, char *buf, const unsigned long *maskp,
			    int nmaskbits)
{
	ptrdiff_t len = PAGE_SIZE - offset_in_page(buf);

	return list ? scnprintf(buf, len, "%*pbl\n", nmaskbits, maskp) :
		      scnprintf(buf, len, "%*pb\n", nmaskbits, maskp);
}
EXPORT_SYMBOL(bitmap_print_to_pagebuf);

/**
 * bitmap_print_to_buf  - convert bitmap to list or hex format ASCII string
 * @list: indicates whether the bitmap must be list
 *      true:  print in decimal list format
 *      false: print in hexadecimal bitmask format
 * @buf: buffer into which string is placed
 * @maskp: pointer to bitmap to convert
 * @nmaskbits: size of bitmap, in bits
 * @off: in the string from which we are copying, We copy to @buf
 * @count: the maximum number of bytes to print
 */
static int bitmap_print_to_buf(bool list, char *buf, const unsigned long *maskp,
		int nmaskbits, loff_t off, size_t count)
{
	const char *fmt = list ? "%*pbl\n" : "%*pb\n";
	ssize_t size;

/* 학습 해설
 * Bitmap Region·반복 구간과 마지막 부분 그룹
 * 위치 목록에 반복적인 선택 패턴을 표현하고 구조체의 필드를 실제 bit 변경으로 연결합니다.
 * Region은 start/end의 inclusive 범위, 그룹 간격 group_len, 각 그룹의 사용 길이 off, 전체 nbits를 갖습니다. Bitmap_set_region은 start부터 group_len씩 증가하며 min(end-start+1,off) bit를 set합니다. 마지막 그룹은 범위의 남은 길이에 맞춰 줄어듭니다. 이 setter 자체는 문법·범위 검사를 수행하지 않습니다.
 * 상위 parser의 check_region이 통과한 region과 충분한 저장 배열을 사용합니다. Off는 여기에서 그룹의 사용 길이이며 출력 slice의 byte offset과 다릅니다. 실제 허용 크기와 start의 unsigned 증가 조건을 유지합니다.
 */
static void bitmap_set_region(const struct region *r, unsigned long *bitmap)
{
	unsigned int start;

	for (start = r->start; start <= r->end; start += r->group_len)
		bitmap_set(bitmap, start, min(r->end - start + 1, r->off));
}

static int bitmap_check_region(const struct region *r)
{
	if (r->start > r->end || r->group_len == 0 || r->off > r->group_len)
		return -EINVAL;

	if (r->end >= r->nbits)
		return -ERANGE;

	return 0;
}

static const char *bitmap_getnum(const char *str, unsigned int *num,
				 unsigned int lastbit)
{
	unsigned long long n;
	unsigned int len;

	if (str[0] == 'N') {

/* 학습 해설
 * Bitmap Region 검사·문법과 범위 오류
 * 사용자가 지정한 반복 구간의 논리 조건과 목적 bitmap의 크기 조건을 별도 오류로 처리합니다.
 * Start>end, group_len0, off>group_len이면 EINVAL입니다. 그다음 end>=nbits이면 ERANGE입니다. 조건을 통과하면 setter가 진행합니다. Bit 위치의 최대값은 nbits-1이므로 end==nbits도 초과입니다. 두 조건이 동시에 틀리면 앞에서 검사한 EINVAL이 먼저 반환됩니다.
 * 반환값 0인 경우만 해당 region을 적용합니다. Off0은 원본 검사가 허용하지만 그룹 길이 0은 loop가 진행하지 않으므로 금지합니다. 전체 parser가 앞서 적용한 다른 region을 자동 되돌리는 지와 이 검사 결과는 별개입니다.
 */
static int bitmap_check_region(const struct region *r)
{
	if (r->start > r->end || r->group_len == 0 || r->off > r->group_len)
		return -EINVAL;

	if (r->end >= r->nbits)
		return -ERANGE;

	return 0;
}

